def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    def is_valid(row, col):
        return 0 <= row < rows and 0 <= col < cols and grid[row][col] == '.'

    def get_neighbors(row, col):
        neighbors = []
        for dr, dc in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            new_row, new_col = row + dr, col + dc
            if is_valid(new_row, new_col):
                neighbors.append((new_row, new_col))
        return neighbors

    queue = [(start, [start])]
    visited = {start}

    while queue:
        (row, col), path = queue.pop(0)

        if (row, col) == goal:
            return path

        for neighbor_row, neighbor_col in get_neighbors(row, col):
            if (neighbor_row, neighbor_col) not in visited:
                visited.add((neighbor_row, neighbor_col))
                queue.append(((neighbor_row, neighbor_col), path + [(neighbor_row, neighbor_col)]))

    return []
