def access_features(grid, start, goal):
    acc = R.access
    feats = {"n_access": len(acc), "grid_copied": R.flags["grid_copied"], "row_slice": R.flags["row_slice"]}
    if not acc:
        return feats
    first = []
    seen = set()
    for cell in acc:
        if cell not in seen:
